import * as THREE from 'three';
import {OrbitControls} from '../vendor/OrbitControls.js';

import {scenes,buildScene} from './omics-scenes.js';
export const modelNotes=Object.fromEntries(Object.entries(scenes).map(([id,s])=>[id,s.parts]));
const palette=[0x9b7dc4,0x6cabc1,0xd0a66d];
export class OmicsModel{
 constructor(host,type,onPick){this.host=host;this.type=type;this.onPick=onPick;this.pickables=[];this.scene=new THREE.Scene();this.scene.background=new THREE.Color('#eff3f7');this.camera=new THREE.PerspectiveCamera(38,1,.1,100);this.camera.position.set(0,1.6,11);this.renderer=new THREE.WebGLRenderer({antialias:true,alpha:false});this.renderer.setPixelRatio(Math.min(devicePixelRatio,1.7));this.renderer.setSize(host.clientWidth,host.clientHeight);host.append(this.renderer.domElement);this.scene.add(new THREE.HemisphereLight(0xffffff,0xa9b6c7,2.6));const light=new THREE.DirectionalLight(0xffffff,3);light.position.set(4,6,8);this.scene.add(light);this.group=new THREE.Group();this.scene.add(this.group);this.controls=new OrbitControls(this.camera,this.renderer.domElement);this.controls.enableDamping=true;this.controls.enablePan=false;this.controls.minDistance=5;this.controls.maxDistance=19;this.controls.autoRotateSpeed=.7;this.build();this.abort=new AbortController();const opts={signal:this.abort.signal};let start;
 this.renderer.domElement.addEventListener('pointerdown',e=>start=[e.clientX,e.clientY],opts);this.renderer.domElement.addEventListener('pointerup',e=>{if(!start||Math.hypot(e.clientX-start[0],e.clientY-start[1])>7)return;const rect=host.getBoundingClientRect(),ray=new THREE.Raycaster();ray.setFromCamera(new THREE.Vector2((e.clientX-rect.left)/rect.width*2-1,-(e.clientY-rect.top)/rect.height*2+1),this.camera);const hit=ray.intersectObjects(this.pickables)[0];if(hit)this.select(hit.object.userData.part);},opts);
 host.addEventListener('keydown',e=>{if(['+','=','-'].includes(e.key)){this.zoom(e.key==='-'?1.15:.87);e.preventDefault();}if(e.key.startsWith('Arrow')){const s=new THREE.Spherical().setFromVector3(this.camera.position);s.theta+=e.key==='ArrowLeft'?-.15:e.key==='ArrowRight'?.15:0;s.phi=Math.max(.15,Math.min(Math.PI-.15,s.phi+(e.key==='ArrowUp'?-.15:e.key==='ArrowDown'?.15:0)));this.camera.position.setFromSpherical(s);e.preventDefault();}},opts);
 this.observer=new ResizeObserver(()=>{const w=host.clientWidth,h=host.clientHeight;if(!w||!h)return;this.camera.aspect=w/h;this.camera.updateProjectionMatrix();this.renderer.setSize(w,h);});this.observer.observe(host);this.camera.aspect=host.clientWidth/host.clientHeight;this.camera.updateProjectionMatrix();this.renderer.setAnimationLoop(()=>{if(document.hidden)return;this.controls.update();this.renderer.render(this.scene,this.camera);});this.select(0);
 }
 mesh(geometry,part,pos=[0,0,0],scale=[1,1,1]){const m=new THREE.Mesh(geometry,new THREE.MeshStandardMaterial({color:palette[part],roughness:.36,metalness:.03}));m.position.set(...pos);m.scale.set(...scale);m.userData.part=part;this.group.add(m);this.pickables.push(m);return m;}
 ball(pos,r,part=0,scale=[1,1,1]){return this.mesh(new THREE.SphereGeometry(r,24,16),part,pos,scale);}
 tube(points,r,part){return this.mesh(new THREE.TubeGeometry(new THREE.CatmullRomCurve3(points.map(p=>new THREE.Vector3(...p))),Math.max(24,points.length*5),r,8,false),part);}
 box(pos,size,part){return this.mesh(new THREE.BoxGeometry(...size),part,pos);}
 ring(pos,r,part){return this.mesh(new THREE.TorusGeometry(r,.055,8,40),part,pos);}
 cone(pos,r,h,part,angle=0){const m=this.mesh(new THREE.ConeGeometry(r,h,12),part,pos);m.rotation.z=angle;return m;}
 poly(pos,r,part){return this.mesh(new THREE.IcosahedronGeometry(r,0),part,pos);}
 label(text,pos){const canvas=document.createElement('canvas');const ctx=canvas.getContext('2d');ctx.font='32px system-ui';canvas.width=Math.ceil(ctx.measureText(text).width)+28;canvas.height=64;ctx.fillStyle='#5b7180';ctx.textAlign='center';ctx.font='32px system-ui';ctx.fillText(text,canvas.width/2,43);const texture=new THREE.CanvasTexture(canvas);const sprite=new THREE.Sprite(new THREE.SpriteMaterial({map:texture,depthTest:false}));sprite.position.set(...pos);sprite.scale.set(Math.min(6,canvas.width/64*.35),.35,1);this.group.add(sprite);}
 build(){buildScene(this,this.type);this.meshSignature=this.pickables.map(m=>[m.geometry.type,m.geometry.attributes.position.count,...m.position.toArray().map(v=>v.toFixed(2)),...m.scale.toArray().map(v=>v.toFixed(2))].join(':')).join('|');}
 isolate(value){this.isolated=value;this.select(this.selected);}

 select(part){this.selected=part;this.pickables.forEach(m=>{m.material.emissive.set(m.userData.part===part?0x17212b:0);m.material.transparent=!!this.isolated;m.material.opacity=this.isolated&&m.userData.part!==part?.13:1;});this.onPick(part);}
 zoom(f){this.camera.position.multiplyScalar(f).clampLength(5,19);this.controls.update();}
 reset(){this.camera.position.set(0,1.6,11);this.controls.autoRotate=false;this.controls.update();}
 getState(){return{type:this.type,part:this.selected,isolated:!!this.isolated,meshCount:this.pickables.length,parts:[0,1,2].map(p=>this.pickables.filter(m=>m.userData.part===p).length),signature:this.meshSignature,position:this.camera.position.toArray(),autoRotate:this.controls.autoRotate};}
 projectPart(part){this.controls.update();this.scene.updateMatrixWorld(true);const ray=new THREE.Raycaster();for(const m of this.pickables.filter(m=>m.userData.part===part)){m.geometry.computeBoundingBox();const candidates=[m.geometry.boundingBox.getCenter(new THREE.Vector3())];const attr=m.geometry.attributes.position;for(let i=0;i<attr.count;i+=Math.max(1,Math.floor(attr.count/30)))candidates.push(new THREE.Vector3().fromBufferAttribute(attr,i).multiplyScalar(.98));for(const q of candidates){const p=m.localToWorld(q).project(this.camera);if(Math.abs(p.x)>1||Math.abs(p.y)>1)continue;ray.setFromCamera(new THREE.Vector2(p.x,p.y),this.camera);if(ray.intersectObjects(this.pickables)[0]?.object.userData.part===part)return{x:(p.x*.5+.5)*this.host.clientWidth,y:(-.5*p.y+.5)*this.host.clientHeight};}}return null;}
 destroy(){this.abort.abort();this.observer.disconnect();this.controls.dispose();this.renderer.setAnimationLoop(null);this.group.traverse(o=>{o.geometry?.dispose();o.material?.map?.dispose();o.material?.dispose();});this.renderer.dispose();this.renderer.forceContextLoss();this.renderer.domElement.remove();}
}
